<script>
$(function(){var t=$('#purchase-receipts-table'),x=$.fn.dataTable.render.text(),prefix='{{ $moduleRoutePrefix }}',classes={DRAFT:'app-status-neutral',APPROVED:'app-status-success',VOID:'app-status-danger'};window.erpInitSelect2('#gr-filter-supplier',{placeholder:'ค้นหา Supplier',allowClear:true,ajax:{url:$('#gr-filter-supplier').data('url'),delay:250,data:function(p){return{q:p.term||'',page:p.page||1};},processResults:function(d){return d;}}});var table=t.DataTable($.extend(true,{},window.erpDataTableDefaults,{ajax:{url:t.data('url'),data:function(d){d.business_date_from=$('#gr-filter-date-from').val();d.business_date_to=$('#gr-filter-date-to').val();d.supplier_id=$('#gr-filter-supplier').val();d.purchase_document_number=$('#gr-filter-purchase-document').val();d.status=$('#gr-filter-status').val();}},order:[[1,'desc']],buttons:[window.erpExcelButton(t)],columns:[{data:'receipt_number',render:x.display},{data:'business_date',render:x.display},{data:'purchase_order_label',render:x.display},{data:'purchase_document_label',render:x.display},{data:'supplier_label',render:x.display},{data:'status_label',render:function(v,type,r){return type==='display'?'<span class="badge '+(classes[r.status]||'app-status-neutral')+'">'+x.display(v||'-')+'</span>':r.status;}},{data:'reason_label',render:function(v,type){return type==='display'&&v&&v!=='-'?'<span class="text-secondary" title="'+x.display(v)+'">'+x.display(v)+'</span>':(v||'-');}},{data:null,orderable:false,searchable:false,className:'text-end text-nowrap',render:function(v,type,r){if(type!=='display')return '';var a=[];if(r.edit_url)a.push('<a class="btn btn-sm btn-app-soft" title="แก้ไข" aria-label="แก้ไข" href="'+x.display(r.edit_url)+'"><i class="bx bx-edit"></i></a>');if(r.can_approve)a.push('<button class="btn btn-sm btn-app-primary js-gr-approve" title="อนุมัติ" aria-label="อนุมัติ" data-url="'+x.display('/'+prefix+'/purchase-receipts/'+r.id+'/approve')+'"><i class="bx bx-check"></i></button>');if(r.can_void)a.push('<button class="btn btn-sm btn-outline-danger js-gr-void" title="ยกเลิก" aria-label="ยกเลิก" data-url="'+x.display('/'+prefix+'/purchase-receipts/'+r.id+'/void')+'"><i class="bx bx-x"></i></button>');return a.join(' ')||'<span class="text-secondary">-</span>';}}]}));function action(b,url,data){b.prop('disabled',true);$.post(url,$.extend({_token:$('meta[name=csrf-token]').attr('content')},data||{})).done(function(r){Swal.fire({icon:'success',text:r.msg||'ดำเนินการแล้ว',timer:1400,showConfirmButton:false});table.ajax.reload(null,false);}).fail(function(xhr){Swal.fire({icon:'error',text:(xhr.responseJSON||{}).message||'ดำเนินการไม่สำเร็จ'});}).always(function(){b.prop('disabled',false);});}t.on('click','.js-gr-approve',function(){var b=$(this);Swal.fire({icon:'warning',title:'อนุมัติ Receipt?',showCancelButton:true,confirmButtonText:'อนุมัติ',cancelButtonText:'ยกเลิก'}).then(function(r){if(r.isConfirmed)action(b,b.data('url'));});});t.on('click','.js-gr-void',function(){var b=$(this);Swal.fire({icon:'warning',title:'ยกเลิก Receipt',input:'textarea',inputLabel:'เหตุผลอย่างน้อย 10 ตัวอักษร',showCancelButton:true,confirmButtonText:'ยกเลิกเอกสาร',cancelButtonText:'กลับ',preConfirm:function(v){if($.trim(v||'').length<10){Swal.showValidationMessage('กรุณาระบุเหตุผล');return false;}return v;}}).then(function(r){if(r.isConfirmed)action(b,b.data('url'),{reason:r.value});});});$('#gr-filter-date-from,#gr-filter-date-to,#gr-filter-status').on('change',function(){table.ajax.reload();});$('#gr-filter-purchase-document').on('input',function(){clearTimeout(window.grDocFilterTimer);window.grDocFilterTimer=setTimeout(function(){table.ajax.reload();},300);});$('#gr-filter-supplier').on('change',function(){table.ajax.reload();});$('#gr-filter-reset').on('click',function(){$('#gr-filter-date-from,#gr-filter-date-to,#gr-filter-purchase-document,#gr-filter-status').val('');$('#gr-filter-supplier').val(null).trigger('change');table.ajax.reload();});table.on('draw',function(){table.rows({page:'current'}).every(function(){var r=this.data(),$cell=$(this.node()).find('td:last');if(r.print_url&&!$cell.find('.js-pdf-print').length)$cell.prepend('<a class="btn btn-sm btn-app-soft js-pdf-print" target="_blank" title="พิมพ์ PDF" aria-label="พิมพ์ PDF" href="'+x.display(r.print_url)+'"><i class="bx bx-printer"></i></a> ');});});});
</script>
